                    if (data.context['时间']) contextHTML += `<div class="context-item"><i class="fas fa-clock"></i>${data.context['时间']}</div>`;
                    if (data.context['地点']) contextHTML += `<div class="context-item"><i class="fas fa-map-marker-alt"></i>${data.context['地点']}</div>`;
                    contextDiv.innerHTML = contextHTML;
                    statusBar.appendChild(contextDiv);
                }

                if (data.characters && data.characters.length > 0) {
                    const header = document.createElement('div');
                    header.className = 'status-bar-header';
                    const tabsDiv = document.createElement('div');
                    tabsDiv.className = 'char-tabs';
                    header.appendChild(tabsDiv);
                    statusBar.appendChild(header);

                    data.characters.forEach((char, index) => {
                        const tab = document.createElement('div');
                        tab.className = 'char-tab';
                        tab.textContent = char.name;
                        tab.dataset.index = index;
                        if (index === 0) {
                            tab.classList.add('active');
                        }
                        tabsDiv.appendChild(tab);

                        const body = document.createElement('div');
                        body.className = 'status-bar-body';
                        if (index === 0) {
                            body.classList.add('active');
                        }
                        body.id = `char-body-${index}`;
                        let html = '<div class="section">';

                        if (char['身份']) html += `<div class="item"><div class="item-key"><i class="fas fa-id-card"></i>身份:</div><div class="item-value">${char['身份']}</div></div>`;
                        if (char['性格']) html += `<div class="item"><div class="item-key"><i class="fas fa-brain"></i>性格:</div><div class="item-value">${char['性格']}</div></div>`;
                        if (char['相貌']) html += `<div class="item"><div class="item-key"><i class="fas fa-user-astronaut"></i>相貌:</div><div class="item-value">${char['相貌']}</div></div>`;
                        if (char['身材']) html += `<div class="item"><div class="item-key"><i class="fas fa-venus"></i>身材:</div><div class="item-value">${char['身材']}</div></div>`;
                        if (char['行动']) html += `<div class="item"><div class="item-key"><i class="fas fa-person-running"></i>行动:</div><div class="item-value">${char['行动']}</div></div>`;

                        if (char['服装']) {
                            const [outer='无', inner='无', shoes='无'] = char['服装'].split('|').map(s => s.trim());
                            html += `<div class="section-title"><i class="fas fa-shirt"></i>当前着装</div><div class="clothing-grid">
                                        <div class="clothing-item"><div class="item-key-sub">外层</div><div>${outer}</div></div>
                                        <div class="clothing-item"><div class="item-key-sub">内衣</div><div>${inner}</div></div>
                                        <div class="clothing-item"><div class="item-key-sub">鞋袜</div><div>${shoes}</div></div>
                                    </div>`;
                        }
                        if (char['内心']) {
                            html += `<div class="section-title"><i class="fas fa-comment-dots"></i>内心独白 (点击显示)</div><div class="inner-thoughts" onclick="this.classList.toggle('revealed')"><div class="item-value">${char['内心']}</div></div>`;
                        }

                        const closeups = Object.entries(char).filter(([k,v]) => v && k.startsWith('特写'));
                        if(closeups.length > 0) {
                            html += `<div class="section-title"><i class="fas fa-eye"></i>感官特写</div><div class="close-up-grid">`;
                            closeups.sort().forEach(([key, value]) => { // sort() to ensure A before B
                                html += `<div class="close-up-cam"><div class="item-value">${value}</div><div class="item-key-sub">${key}</div></div>`;
                            });
                            html += `</div>`;
                        }
                        html += '</div>';

                        body.innerHTML = html;
                        statusBar.appendChild(body);
                    });

                    function switchTab(index) {
                        root.querySelectorAll('.char-tab').forEach(t => t.classList.remove('active'));
                        root.querySelectorAll('.status-bar-body').forEach(b => b.classList.remove('active'));
                        const activeTab = root.querySelector(`.char-tab[data-index='${index}']`);
                        const activeBody = root.querySelector(`#char-body-${index}`);
                        if (activeTab && activeBody) {
                            activeTab.classList.add('active');
                            activeBody.classList.add('active');
                        }
                    }
                    tabsDiv.addEventListener('click', (e) => {
                        if (e.target.classList.contains('char-tab')) switchTab(e.target.dataset.index);
                    });
                }

                if (data.options && data.options.length > 0) {
                    let optionsHTML = `<div class="action-options">
                                        <details open>
                                            <summary><i class="fas fa-tasks"></i>行动选项</summary>
                                            <ul class="options-list">`;
                    data.options.forEach(opt => {
                        const match = opt.match(/^\(([^)]+)\)(.*)/);
                        const actionText = opt.trim();
                        if (match) {
                           optionsHTML += `<li data-action="${actionText}"><span class="option-type">(${match[1]})</span>${match[2].trim()}</li>`;
                        } else {
                           optionsHTML += `<li data-action="${actionText}">${actionText}</li>`;
                        }
                    });
                    optionsHTML += `       </ul>
                                        </details>
                                     </div>`;
                    statusBar.insertAdjacentHTML('beforeend', optionsHTML);
                }

                root.appendChild(statusBar);

                root.addEventListener('click', function(e) {
                    const targetLi = e.target.closest('.options-list li');
                    if (targetLi) {
                        const actionText = targetLi.dataset.action;
                        sendToChatBox(actionText);
                        const details = targetLi.closest('details');
                        if(details) details.open = false;
                    }
                });
            }

            const rawData = dataContainer.textContent.trim();
            if (rawData) {
                try {
                    const parsedData = parseData(rawData);
                    render(parsedData);
                } catch (error) {
                    console.error("Failed to parse or render status bar data:", error);
                    root.innerHTML = `<div style="color:red; padding:10px;">状态栏数据解析或渲染失败: ${error.message}</div>`;
                }
            }
        });
    </script>
</body>
</html>
